<?php
require_once __DIR__.'/../lib/bootstrap.php'; require_login();
$aid=get_int('id');$u=current_user();
$owner=$u['role']==='admin'?'':' AND (a.student_id=? OR e.created_by=?)';$params=$u['role']==='admin'?[$aid]:[$aid,(int)$u['id'],(int)$u['id']];
$s=db()->prepare("SELECT a.*,e.title exam_title,e.total_score,e.created_by,e.subject_id,u.full_name student_name,s.title subject_title,c.title class_title FROM attempts a JOIN exams e ON e.id=a.exam_id JOIN users u ON u.id=a.student_id JOIN subjects s ON s.id=e.subject_id JOIN classes c ON c.id=e.class_id WHERE a.id=?$owner");$s->execute($params);$attempt=$s->fetch();if(!$attempt)exit('گزارش پیدا نشد یا مجوز ندارید.');
$s=db()->prepare('SELECT q.question_text,q.chapter,q.question_type,q.score,a.awarded_score,a.is_correct,a.teacher_comment,o.option_text selected_text FROM answers a JOIN questions q ON q.id=a.question_id LEFT JOIN question_options o ON o.id=a.selected_option_id WHERE a.attempt_id=? ORDER BY q.sort_order');$s->execute([$aid]);$answers=$s->fetchAll();
function student_xls_cell($value){return '"'.str_replace('"','""',(string)$value).'"';}
$filename='student_result_'.$aid.'_'.date('Ymd_His').'.xls';header('Content-Type: application/vnd.ms-excel; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'"');echo "\xEF\xBB\xBF";echo student_xls_cell('کارنامه دانش‌آموز')."\t".student_xls_cell($attempt['student_name'])."\n";echo student_xls_cell('آزمون')."\t".student_xls_cell($attempt['exam_title'])."\n";echo student_xls_cell('درس')."\t".student_xls_cell($attempt['subject_title'])."\n";echo student_xls_cell('کلاس')."\t".student_xls_cell($attempt['class_title'])."\n";echo student_xls_cell('نمره')."\t".student_xls_cell($attempt['score']??0)." / ".student_xls_cell($attempt['total_score'])."\n";echo student_xls_cell('درصد')."\t".student_xls_cell($attempt['percentage']??0)."%\n\n";echo implode("\t",array_map('student_xls_cell',['ردیف','فصل / مبحث','نوع سؤال','متن سؤال','پاسخ انتخابی','نمره سؤال','نمره کسب‌شده','وضعیت','بازخورد معلم']))."\n";foreach($answers as $i=>$a){$status=$a['is_correct']===null?'نیازمند بررسی':((int)$a['is_correct']?'صحیح':'نادرست');echo implode("\t",array_map('student_xls_cell',[$i+1,$a['chapter']??'',$a['question_type'],$a['question_text'],$a['selected_text']??$a['answer_text']??'بدون پاسخ',$a['score'],$a['awarded_score']??0,$status,$a['teacher_comment']??'']))."\n";}exit;
